/**
 * context-compressor.ts — 机械上下文压缩器
 *
 * B3: 对标 Claw-Code compact.rs 的纯文本机械压缩。
 * 不调 LLM。纯统计+截断+固顶。
 *
 * 核心原则（来自 Claw-Code 分析）：
 *   1. 零 LLM 调用 — 纯文本处理，统计+截断
 *   2. 严格有界 — 压缩后 = 1 条摘要 + N 条最近消息
 *   3. ToolUse/ToolResult 配对保护 — 绝不拆散工具调用对
 *   4. 重复压缩合并 — 旧摘要展平，避免摘要之摘要膨胀
 *
 * Synova 适配：
 *   - 诊断阶段消息替代对话消息
 *   - 证据条目替代文件操作
 *   - Phase 边界作为压缩触发点
 */
export interface CompactionConfig {
    /** 保留最近 N 条消息（对标 Claw-Code preserve_recent_messages=4） */
    preserveRecentMessages: number;
    /** 触发压缩的估算 Token 阈值（对标 100_000） */
    maxEstimatedTokens: number;
    /** 每条消息截断字符数（对标 Claw-Code 160） */
    truncateChars: number;
    /** 摘要最大字符数 */
    maxSummaryChars: number;
}
export declare const DEFAULT_COMPACTION_CONFIG: CompactionConfig;
export interface ConversationMessage {
    role: 'system' | 'user' | 'assistant' | 'tool';
    content: string;
    /** 消息所属的诊断阶段（0-5） */
    phase?: number;
    /** 工具调用名（tool 角色时） */
    toolName?: string;
    /** 是否是工具调用结果 */
    isToolResult?: boolean;
    /** 是否是工具调用 */
    isToolUse?: boolean;
    /** 估算 Token 数 */
    estimatedTokens?: number;
}
export interface CompactionResult {
    /** 压缩后的消息列表 */
    compactedMessages: ConversationMessage[];
    /** 移除的消息数 */
    removedMessageCount: number;
    /** 压缩摘要 */
    summary: string;
    /** 节省的估算 Token 数 */
    tokensSaved: number;
    /** 压缩次数（用于检测重复压缩） */
    compactionCount: number;
}
export declare function shouldCompact(messages: ConversationMessage[], config?: CompactionConfig): boolean;
export declare function compactMessages(messages: ConversationMessage[], previousSummary?: string, config?: CompactionConfig): CompactionResult;
/** 重置压缩计数（测试用） */
export declare function resetCompactionCount(): void;
